//! Crate-backed material/texture binding + original decoded-image boundary.
#[cfg(all(feature="mesh-import",feature="material-textures"))]
mod enabled{
use super::super::{texture_material::{Image,Surface,Slot,Wrap},vertex_stream::Stream};
#[derive(serde::Serialize,serde::Deserialize)]pub struct Asset{pub streams:Vec<Stream>,pub surfaces:Vec<Surface>,pub images:Vec<Image>,pub metadata:serde_json::Value}
fn slot(texture:gltf::Texture<'_>,uv:u32)->Result<Slot,String>{if uv!=0{return Err("material adapter supports TEXCOORD_0 only".into());}use gltf::texture::{WrappingMode as W,MinFilter as F,MagFilter};let s=texture.sampler();let wrap=|w|match w{W::ClampToEdge=>Wrap::Clamp,W::MirroredRepeat=>Wrap::Mirror,W::Repeat=>Wrap::Repeat};let min=match s.min_filter(){Some(F::Nearest)=>false,Some(F::Linear)|None=>true,_=>return Err("mipmap minification unsupported: choose explicit level0 nearest/linear sampler".into())};let mag=match s.mag_filter(){Some(MagFilter::Nearest)=>false,_=>true};if min!=mag{return Err("mixed min/mag filtering requires derivatives; unsupported by level0 draft".into());}Ok(Slot{image:texture.source().index(),wrap_s:wrap(s.wrap_s()),wrap_t:wrap(s.wrap_t()),linear:mag})}
fn material(m:gltf::Material<'_>)->Result<Surface,String>{if m.alpha_mode()!=gltf::material::AlphaMode::Opaque||m.emissive_factor()!=[0.;3]||m.emissive_texture().is_some(){return Err("draft supports opaque nonemissive metallic-roughness only".into());}let p=m.pbr_metallic_roughness();let f=p.base_color_factor();let base=p.base_color_texture().map(|s|slot(s.texture(),s.tex_coord())).transpose()?;let mr=p.metallic_roughness_texture().map(|s|slot(s.texture(),s.tex_coord())).transpose()?;let normal=m.normal_texture();let ao=m.occlusion_texture();Ok(Surface{albedo:[f[0] as f64,f[1] as f64,f[2] as f64],metallic:p.metallic_factor() as f64,roughness:p.roughness_factor() as f64,base,metal_rough:mr,normal:normal.as_ref().map(|s|slot(s.texture(),s.tex_coord())).transpose()?,occlusion:ao.as_ref().map(|s|slot(s.texture(),s.tex_coord())).transpose()?,ao_strength:ao.as_ref().map(|s|s.strength() as f64).unwrap_or(1.),normal_scale:normal.as_ref().map(|s|s.scale() as f64).unwrap_or(1.),double_sided:m.double_sided()})}
/// No external fetches/paths: caller supplies decoded RGBA8 by glTF image index.
/// URI and buffer-view image bytes decoding is a separate explicit boundary.
pub fn load(bytes:&[u8],buffers:&[Vec<u8>],images:Vec<Image>,scene:usize)->Result<Asset,String>{let g=gltf::Gltf::from_slice(bytes).map_err(|e|e.to_string())?;if g.document.extensions_used().next().is_some(){return Err("material draft rejects extensions rather than discard them".into());}if g.document.images().len()!=images.len(){return Err("supply decoded images in exact glTF image-index order".into());}let raw=super::super::ingest::gltf(bytes,buffers,true)?;let baked=super::super::node_ingest::instantiate(bytes,buffers,true,scene)?;let mut materials=Vec::new();for mesh in g.document.meshes(){for p in mesh.primitives(){materials.push(material(p.material())?);}}let instances=baked.metadata["instances"].as_array().ok_or("baked instance metadata absent")?;let mut streams=Vec::with_capacity(instances.len());let mut surfaces=Vec::with_capacity(instances.len());for i in instances{let source=i["source_stream"].as_u64().ok_or("source stream absent")? as usize;let surface=materials.get(source).ok_or("source material absent")?.clone();surface.validate(&images)?;let mut stream=raw.streams.get(source).ok_or("source geometry absent")?.clone();if surface.normal.is_some(){stream=super::super::mikk_adapter::generate(&stream)?;}let world:super::super::mesh::Matrix=serde_json::from_value(i["world_matrix_row_major"].clone()).map_err(|e|e.to_string())?;streams.push(super::super::node_ingest::transform(&stream,world)?);surfaces.push(surface);}Ok(Asset{streams,surfaces,images,metadata:serde_json::json!({"scene":scene,"scene_transforms_applied":true,"material_mapping_applied":true,"mikk":"generated in object space before node transform for normal-mapped primitives","image_boundary":"explicit decoded RGBA8 by image index; no URI IO","filtering":"level0 nearest/linear; explicit mipmap/mixed filters rejected","alpha":"opaque only","extensions":"rejected"})})}
}
#[cfg(all(feature="mesh-import",feature="material-textures"))]pub use enabled::{Asset,load};
